  # rollback trigger); the artifact must be fresh
  set +e
  node -e 'const j=JSON.parse(require("fs").readFileSync(process.argv[1]));const want=process.argv[2].split(",");const clock=process.argv[3];const basePath=process.argv[4];const base=basePath?JSON.parse(require("fs").readFileSync(basePath)):null;const age=(Date.now()-Date.parse(j.generated_at))/1000;let bad=[],notes=[];const snap={};for(const f of j.feeds){const id=f.catalog&&f.catalog.feed_id;if(!want.includes(id))continue;const comps=f.components||{};snap[id]={};for(const [k,c] of Object.entries(comps))snap[id][k]=c.status;const tc=comps.time_contract||{};const st=f.overall||f.status;console.log(id,st,"time_contract:",tc.status,(tc.summary||"").slice(0,100),"clock:",f.catalog.publisher_time_clock,"valid_share:",f.catalog.content_time_valid_share,"floor:",f.catalog.content_time_cutover_min_valid_share,"rev:",f.catalog.catalog_revision);if(tc.status!=="OK")bad.push(id+" time_contract="+tc.status);if(f.catalog.publisher_time_clock!==clock)bad.push(id+" clock="+f.catalog.publisher_time_clock);if(clock==="content_time_v1"&&Math.abs(Number(f.catalog.content_time_cutover_min_valid_share)-Number(process.argv[5]))>1e-9)bad.push(id+" floor="+f.catalog.content_time_cutover_min_valid_share+" != expected "+process.argv[5]);const nc=comps.ner_coverage||{};console.log(id,"ner_coverage:",nc.status,(nc.summary||"").slice(0,120));for(const [k,c] of Object.entries(comps)){if(k==="time_contract")continue;if(k==="ner_coverage"||k==="embedding_coverage"){if(c.status!=="OK"&&c.status!=="SKIP")notes.push(id+" "+k+"="+c.status+" (preprocessing-coverage lane: windows on createdAt/indexedAt, clock-independent -- recorded, not gated)");continue}const b=base&&base[id]&&base[id][k];const rank=(x)=>x==="OK"?0:x==="SKIP"?0:x==="WARN"?1:x==="FAIL"?2:1;if(!base){if(c.status!=="OK"&&c.status!=="SKIP")notes.push(id+" "+k+"="+c.status+" (baseline run: recorded, not gated)");}else if(c.status==="FAIL"&&(b===undefined||rank(c.status)>rank(b)))bad.push(id+" "+k+" regressed to FAIL (baseline "+(b||"n/a")+")");else if(c.status!=="OK"&&c.status!=="SKIP")notes.push(id+" "+k+"="+c.status+" (baseline "+(b||"n/a")+", pre-existing)");}}require("fs").writeFileSync("/tmp/rc."+process.pid+".json",JSON.stringify(snap));console.log("snapshot=/tmp/rc."+process.pid+".json");console.log("generated_at",j.generated_at,"age_s",Math.round(age));if(notes.length)console.log("pre-existing non-OK (not gated): "+notes.join("; "));if(bad.length){console.log("GATE: "+bad.join("; "));process.exit(2)}' /tmp/fr.$$ "$EXPECTED_UPDATE_RKEYS" "$EXPECTED_CLOCK" "$basef" "$EXPECTED_FLOOR" > /tmp/rg.$$ ; local rrc=$?; set -e
  emit readiness-gate.txt < /tmp/rg.$$; local snapf; snapf=$(sed -n 's/^snapshot=//p' /tmp/rg.$$); [[ -n "$snapf" && -f "$snapf" ]] && { emit readiness-components.json < "$snapf"; rm -f "$snapf"; }; rm -f /tmp/rg.$$ /tmp/fr.$$
  (( rrc == 0 )) || die "GATE FAIL: readiness (time_contract not OK, wrong clock, or a component regressed to FAIL vs the baseline -- see readiness-gate.txt); if the composite merely predates the apply, wait for the health tick and re-run"
  # (6) rollback dry-run (D3(v)) INTO THIS BATTERY DIR: after apply the restore body must be valid against the activated rows (mandatory)
  if [[ "$EXPECTED_CLOCK" == "content_time_v1" ]]; then [[ -f "$E0/feedgen-bulk-rollback.json" && -f "$E0/apply-transport.txt" ]] || die "battery under content_time_v1 requires the apply artifacts in $E0"; load_keys; local n=0; while IFS= read -r u; do local rk2; rk2=$(node -e 'console.log(JSON.parse(process.argv[1]).rkey)' "$u"); curl --fail -sS --max-time 30 -H "@$HDR" -H 'content-type: application/json' --data-binary "$u" "$FEEDGEN_URL/api/admin/feed_catalog/dry-run" | emit "rollback-dry-run-$rk2.json"; dry_run_gate "$E/rollback-dry-run-$rk2.json" || die "rollback dry-run $rk2 not clean"; n=$((n+1)); done < <(node -e 'const j=JSON.parse(require("fs").readFileSync(process.argv[1]));for(const u of j.updates)console.log(JSON.stringify(u))' "$E0/feedgen-bulk-rollback.json"); echo "rollback_dry_run_rows_ok=$n" | emit rollback-dry-run-gate.txt; rm -f "$HDR"; HDR=""; fi
  # (7) conformance summary (sudo scan) -- fail closed if the scan itself fails
  local cs rc=0; cs=$( ( set -a; . "$ENV_FILE"; set +a; "$BSKYOPS" ecosystem conformance scan --json 2>/dev/null ) ) || rc=$?   # canonical invocation (runbook): root + feedgen env sourced, else the L1 readbacks report "blocked"   # rc=1 means "drift" (a verdict, not a failure); no JSON = failure
  echo "$cs" | node -e 'let s="";process.stdin.on("data",d=>s+=d).on("end",()=>{const j=JSON.parse(s);const base=new Set(process.argv[2].split(",").filter(Boolean));const items=j.checks||j.items||j.results||[];const arr=Array.isArray(items)?items:Object.entries(items).map(([k,v])=>({name:k,...v}));const nonok=arr.filter(x=>x&&x.status&&x.status!=="ok").map(x=>(x.name||x.check)+"="+x.status);const newDrift=nonok.filter(n=>!base.has(n.split("=")[0]));if(!arr.length){const dc=(j.summary||{}).drift_count||0;if(dc>base.size)newDrift.push("drift_count="+dc+">"+base.size)}console.log("summary="+JSON.stringify(j.summary)+" scan_rc="+process.argv[1]+" non_ok="+nonok.join(",")+" baseline="+[...base].join(",")+" new_non_ok="+newDrift.join(","));if(newDrift.length||((j.summary||{}).blocked_count||0)>0)process.exit(2)})' "$rc" "$CONFORMANCE_BASELINE_DRIFT" | emit conformance.txt || die "conformance: new drift or blocked items beyond the recorded baseline (see conformance.txt)"
  local last_start; last_start=$(echo "$hdr" | sed -n 's/.*LAST_RUN_START=\(\S*\).*/\1/p'); [[ -n "$last_start" ]] || last_start=$run_start
  if [[ "$EXPECTED_CLOCK" == "content_time_v1" ]]; then echo "$last_start" | sed -E 's/\.([0-9]{3})[0-9]*/.\1/; s/\+00:00$/Z/' > /tmp/lrs.$$; install -o root -g newsflows -m 640 /tmp/lrs.$$ "$E0/battery-last-run-start.txt.$L"; cp -f "$E0/battery-last-run-start.txt.$L" "$E0/battery-last-run-start.txt"; rm -f /tmp/lrs.$$; fi
  E=$E0; log "battery $L complete: all gates passed (receipts in $B)"
}
case "${1:-}" in preview) cmd_preview;; apply) cmd_apply;; parity) cmd_parity;; rollback-dryrun) cmd_rollback_dryrun;; rollback) cmd_rollback;; battery) cmd_battery "${2:?label}";; *) echo "usage: $0 preview|apply|parity|rollback-dryrun|rollback|battery <label>" >&2; exit 2;; esac
